"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Check, X } from "@/components/ui/icons";

// Chip: generated by UIX from the design system. Same variants and sizes as the Figma component.

const chipVariants = cva(
  "inline-flex items-center transition-colors gap-1-5 px-3 py-1-5 text-label-medium has-[:focus-visible]:ring-3 has-[:focus-visible]:ring-line-focus rounded-full",
  {
    variants: {
      appearance: {
        filled: "bg-subtle hover:bg-muted text-fg-primary data-[state=selected]:bg-brand data-[state=selected]:text-fg-on-brand data-[state=disabled]:bg-disabled data-[state=disabled]:text-fg-disabled data-[state=disabled]:pointer-events-none",
        outline: "border border-line-default hover:bg-subtle text-fg-primary data-[state=selected]:bg-brand-subtle data-[state=selected]:text-fg-brand data-[state=selected]:border-line-brand data-[state=disabled]:bg-disabled data-[state=disabled]:text-fg-disabled data-[state=disabled]:border-line-default data-[state=disabled]:pointer-events-none",
        soft: "bg-subtle hover:bg-muted text-fg-primary data-[state=selected]:bg-brand-subtle data-[state=selected]:text-fg-brand data-[state=disabled]:bg-disabled data-[state=disabled]:text-fg-disabled data-[state=disabled]:pointer-events-none",
      },
    },
    defaultVariants: {
      appearance: "filled",
    },
  },
);

export interface ChipProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, "onClick">,
    VariantProps<typeof chipVariants> {
  selected?: boolean;
  disabled?: boolean;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  /** Avatar before the label (for example <Avatar size="xs" initials="AB" />). */
  leadingAvatar?: React.ReactNode;
  /** Icon before the label. */
  leadingIcon?: React.ReactNode;
  /** Shows a remove button and calls this when it is pressed. */
  onRemove?: () => void;
}

const Chip = React.forwardRef<HTMLSpanElement, ChipProps>(
  ({ className, appearance, selected = false, disabled = false, onClick, leadingAvatar, leadingIcon, onRemove, children, ...props }, ref) => (
    <span data-slot="chip" data-kind="chip"
      ref={ref}
      data-state={disabled ? "disabled" : selected ? "selected" : "idle"}
      className={cn(chipVariants({ appearance }), className)}
      {...props}
    >
      <button type="button" disabled={disabled} aria-pressed={selected} onClick={onClick} className="inline-flex cursor-pointer items-center gap-1.5 rounded-[inherit] outline-none">
        {leadingAvatar}
        {leadingIcon}
        {selected ? <Check aria-hidden className="size-[14px]" /> : null}
        {children}
      </button>
      {onRemove ? (
        <button type="button" aria-label="Remove" disabled={disabled} onClick={onRemove} className="inline-flex cursor-pointer items-center gap-1.5 rounded-[inherit] outline-none">
          <X aria-hidden className="size-[14px]" />
        </button>
      ) : null}
    </span>
  ),
);
Chip.displayName = "Chip";

export { Chip, chipVariants };
